function calculatorHTML(){
 return `<dialog class="sum-tool" data-sum-tool aria-label="Rechenhilfe"><header class="sum-head"><button type="button" class="sum-grip" data-sum-grip aria-label="Rechenhilfe verschieben" title="Zum Verschieben ziehen oder Pfeiltasten nutzen"><span aria-hidden="true">⠿</span><strong>Rechenhilfe</strong><small>+ / −</small></button><button type="button" class="sum-close" data-action="sum-close" aria-label="Rechenhilfe schließen">${icon('close',20)}</button></header><div class="sum-body"><p class="sum-expression" data-sum-expression aria-label="Deine Rechnung"></p><output data-sum-display aria-live="polite">0,00</output><div class="sum-keys">${[['clear','C'],['back','⌫'],['7','7'],['8','8'],['9','9'],['-','−'],['4','4'],['5','5'],['6','6'],['+','+'],['1','1'],['2','2'],['3','3'],['equals','='],['0','0'],[',',',']].map(([key,label])=>`<button type="button" data-action="sum-key" data-key="${key}" aria-label="${{clear:'Rechnung löschen',back:'Letzte Ziffer löschen','-':'Minus','+':'Plus',equals:'Ergebnis berechnen',',':'Dezimalkomma'}[key]||label}" class="sum-key-${key==='+'?'plus':key==='-'?'minus':key===','?'comma':key} ${['+','-','equals'].includes(key)?'sum-operator':''}" ${key==='clear'?'autofocus':''}>${label}</button>`).join('')}</div><p class="sum-error" data-sum-error role="status"></p><p class="sum-target" data-sum-target>Wähle ± am Betragsfeld.</p><button type="button" class="btn tiny sum-accept" data-action="sum-accept" disabled>Ergebnis übernehmen</button></div></dialog>`;
}
function calculatorState(host){let calc=calculators.get(host);if(!calc){calc=BioCasaCalculator.create();calculators.set(host,calc);}return calc;}
function refreshCalculator(host){const v=calculatorState(host).view(),target=calculatorTargets.get(host);host.querySelector('[data-sum-display]').textContent=v.display;host.querySelector('[data-sum-expression]').textContent=v.expression;host.querySelector('[data-sum-error]').textContent=v.error;host.querySelector('[data-sum-target]').textContent=target?'Übernehmen in: '+target.label:'Wähle ± am Betragsfeld.';host.querySelector('[data-action="sum-accept"]').disabled=v.value===null||!target||target.input.isConnected===false;}
function amountInputHTML(input,label){return `<span class="amount-input" data-sum-field>${input}<button type="button" class="sum-open" data-action="sum-open" data-label="${esc(label)}" aria-label="Rechenhilfe für ${esc(label)} öffnen" title="Rechenhilfe">±</button></span>`;}
function placeCalculator(){
 const host=activeCalculator,target=host&&calculatorTargets.get(host);if(!host?.open||!target)return;
 const viewport=window.visualViewport,vx=viewport?.offsetLeft||0,vy=viewport?.offsetTop||0,vw=viewport?.width||window.innerWidth,vh=viewport?.height||window.innerHeight;
 if(!vw||!vh)return;
 host.style.maxHeight=Math.max(120,vh-24)+'px';
 const box=host.getBoundingClientRect(),anchor=target.button.getBoundingClientRect(),clamp=(n,min,max)=>Math.max(min,Math.min(n,max));
 let x=anchor.right+10;if(x+box.width>vx+vw-12)x=anchor.left-box.width-10;if(x<vx+12)x=anchor.right-box.width;
 let y=anchor.bottom+box.height+10<=vy+vh-12?anchor.bottom+10:anchor.top-box.height-10;
 const position=calculatorPositions.get(host);if(position){x=position.x;y=position.y;}
 x=clamp(x,vx+12,vx+vw-box.width-12);y=clamp(y,vy+12,vy+vh-box.height-12);
 host.style.left=x+'px';host.style.top=y+'px';if(position)calculatorPositions.set(host,{x,y});
}
function beginCalculatorDrag(event){
 if(!activeCalculator)return false;const grip=event.target.closest('[data-sum-grip]');if(!grip||grip.closest('[data-sum-tool]')!==activeCalculator||event.isPrimary===false||event.button>0)return false;
 event.preventDefault();grip.focus();const box=activeCalculator.getBoundingClientRect();calculatorDrag={host:activeCalculator,grip,id:event.pointerId,x:event.clientX,y:event.clientY,left:box.left,top:box.top};grip.setPointerCapture?.(event.pointerId);return true;
}
function moveCalculator(event){const d=calculatorDrag;if(!d||event.pointerId!==d.id)return;event.preventDefault();calculatorPositions.set(d.host,{x:d.left+event.clientX-d.x,y:d.top+event.clientY-d.y});placeCalculator();}
function endCalculatorDrag(event){const d=calculatorDrag;if(!d||(event&&event.pointerId!==d.id))return;calculatorDrag=null;if(d.grip.hasPointerCapture?.(d.id))d.grip.releasePointerCapture(d.id);}
function closeCalculator(restore=true){const host=activeCalculator;if(!host)return;endCalculatorDrag();const target=calculatorTargets.get(host);activeCalculator=null;host.close();if(restore&&target?.button.isConnected!==false)target?.button.focus();}
function openCalculator(el){const input=el.closest('[data-sum-field]')?.querySelector('input');if(!input||input.disabled||input.readOnly)return;const scope=input.closest('form'),host=scope?.querySelector('[data-sum-tool]');if(!host)return;closeCalculator(false);calculatorTargets.set(host,{input,label:el.dataset.label,button:el});activeCalculator=host;refreshCalculator(host);host.showModal();placeCalculator();}
function useCalculator(el){const host=el.closest('[data-sum-tool]');if(!host)return;calculatorState(host).press(el.dataset.key);refreshCalculator(host);}
function acceptCalculator(el){const host=el.closest('[data-sum-tool]'),v=calculatorState(host).view(),target=calculatorTargets.get(host);if(v.value===null||!target||target.input.isConnected===false||target.input.disabled||target.input.readOnly)return;const input=target.input;closeCalculator(false);input.value=(v.value/100).toFixed(2).replace('.',',');input.dispatchEvent(new window.Event('input',{bubbles:true}));input.dispatchEvent(new window.Event('change',{bubbles:true}));input.focus();}
function closingAccountChoices(name,value=''){return `<fieldset class="closing-choices"><legend>Welches Abschlusskonto?</legend>${[['800','Eröffnungsbilanzkonto (EBK)'],['801','Schlussbilanzkonto (SBK)'],['802','Gewinn- und Verlustkonto (GuV)'],['0','Keine Abschlussbuchung']].map(([id,title])=>`<label><input type="radio" name="${name}" value="${id}" ${value===id?'checked':''}><span>${id==='0'?'':id+' · '}<strong>${title}</strong></span></label>`).join('')}</fieldset>`;}
