function closingResultHTML(m,proofState=state){
 if(!m.amount)return tAccountHTML(m,{closed:true})+'<p class="help-text">Seitensummen gleich: kein Saldo, keine Gegenbuchung.</p>';
 const target=A.closing(m);
 return `<div class="closing-explanation" role="status"><span>Summe Soll: ${euro(m.debit)} · Summe Haben: ${euro(m.credit)}</span><strong>Dein geprüfter Saldo: ${euro(m.amount)}</strong><span>Abschlusseintrag im ${m.side==='d'?'Soll':'Haben'} von ${accountCaption(m.id)} → Gegenbuchung im ${target.counterSide==='d'?'Soll':'Haben'} von ${accountCaption(target.counter)}</span></div><div class="closing-transfer"><section><h4>1 · Kontoausgleich</h4>${tAccountHTML(m,{closed:true})}</section><div class="closing-transfer-arrow" aria-hidden="true">→</div><section><h4>2 · Gegenbuchung</h4>${tAccountHTML(A.counterModel(proofState,m))}</section></div><p class="help-text">Orange verbindet beide Einträge. Das ${m.balance?'Schlussbilanzkonto':'GuV-Konto'} sammelt die geprüften Abschlüsse; das Journal bleibt erhalten.</p>`;
}
